sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // --------------------------------------------------
    // Helper function:
    // Find the Staff Shift record for a staff member
    // --------------------------------------------------
    function getStaffShift(staffSysId) {

        if (!staffSysId) {
            return null;
        }

        var shift = new GlideRecord('x_snc_flowops_staff_shift');

        shift.addQuery('staff', staffSysId);
        shift.addQuery('shift_status', 'Active');
        shift.setLimit(1);
        shift.query();

        if (shift.next()) {
            return shift;
        }

        return null;
    }


    // --------------------------------------------------
    // 1. NEW HOUSEKEEPING TASK
    // --------------------------------------------------

    if (current.operation() == 'insert') {

        // Only count tasks that are not already finished/escalated
        var status = current.getDisplayValue('status');

        if (
            current.assigned_staff &&
            status != 'Escalated' &&
            status != 'Resolved'
        ) {

            var newShift = getStaffShift(
                current.assigned_staff.toString()
            );

            if (newShift) {

                var count = parseInt(
                    newShift.assigned_room_count,
                    10
                ) || 0;

                newShift.assigned_room_count = count + 1;
                newShift.update();
            }
        }

        return;
    }


    // --------------------------------------------------
    // 2. EXISTING TASK UPDATE
    // --------------------------------------------------

    // If staff assignment changed
    if (current.assigned_staff.changes()) {

        // Remove count from OLD staff
        if (previous.assigned_staff) {

            var oldShift = getStaffShift(
                previous.assigned_staff.toString()
            );

            if (oldShift) {

                var oldCount = parseInt(
                    oldShift.assigned_room_count,
                    10
                ) || 0;

                oldShift.assigned_room_count =
                    Math.max(0, oldCount - 1);

                oldShift.update();
            }
        }


        // Add count to NEW staff
        if (
            current.assigned_staff &&
            current.getDisplayValue('status') != 'Escalated' &&
            current.getDisplayValue('status') != 'Resolved'
        ) {

            var newAssignedShift = getStaffShift(
                current.assigned_staff.toString()
            );

            if (newAssignedShift) {

                var newCount = parseInt(
                    newAssignedShift.assigned_room_count,
                    10
                ) || 0;

                newAssignedShift.assigned_room_count =
                    newCount + 1;

                newAssignedShift.update();
            }
        }

        return;
    }


    // --------------------------------------------------
    // 3. STATUS CHANGED TO ESCALATED OR RESOLVED
    // --------------------------------------------------

    if (current.status.changes()) {

        var newStatus = current.getDisplayValue('status');
        var oldStatus = previous.getDisplayValue('status');

        // Only decrease when moving FROM an active state
        // TO Escalated or Resolved.

        var wasActive =
            oldStatus != 'Escalated' &&
            oldStatus != 'Resolved';

        var isFinished =
            newStatus == 'Escalated' ||
            newStatus == 'Resolved';

        if (
            wasActive &&
            isFinished &&
            current.assigned_staff
        ) {

            var completedShift = getStaffShift(
                current.assigned_staff.toString()
            );

            if (completedShift) {

                var currentCount = parseInt(
                    completedShift.assigned_room_count,
                    10
                ) || 0;

                completedShift.assigned_room_count =
                    Math.max(0, currentCount - 1);

                completedShift.update();
            }
        }
    }

})(current, previous);
